using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "AgonyCustomTag", menuName = "Data/Battle/Battle Actions/Tags/AgonyCustomTag", order = 0)]
public class AgonyCustomTag : Tag
{
	[SerializeField]
	private Effect effectToReceive;

	public override string GetTagDescription()
	{
		return Smart.Format(base.GetTagDescription(), ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedAtTheEndOfTheirTurn().LowercaseFirst().RemoveLast());
	}
}
